import { useState } from 'react';
import AlertList from './screens/AlertList';
import CreateAlert from './screens/CreateAlert';
import AlertTriggered from './screens/AlertTriggered';
import Watchlist from './screens/Watchlist';

export default function App() {
  const [screen, setScreen] = useState('AlertList');
  const [selectedTicker, setSelectedTicker] = useState<string | null>(null);
  const [triggeredAlert, setTriggeredAlert] = useState<{ ticker: string; price: number; direction: string } | null>(null);

  const navigate = (s: string, params?: any) => {
    if (params?.ticker) setSelectedTicker(params.ticker);
    if (params?.alert) setTriggeredAlert(params.alert);
    setScreen(s);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex justify-center">
      <div className="w-full max-w-sm bg-white min-h-screen flex flex-col shadow-xl">
        {screen === 'AlertList' && <AlertList navigate={navigate} />}
        {screen === 'CreateAlert' && <CreateAlert navigate={navigate} ticker={selectedTicker} />}
        {screen === 'AlertTriggered' && <AlertTriggered navigate={navigate} alert={triggeredAlert} />}
        {screen === 'Watchlist' && <Watchlist navigate={navigate} />}
      </div>
    </div>
  );
}

