import { useState } from 'react';
import { mockAlerts } from '../data/mock-data';

export default function AlertList({ navigate }: { navigate: (s: string, p?: any) => void }) {
  const [alerts, setAlerts] = useState(mockAlerts);

  const deleteAlert = (id: number) => setAlerts(a => a.filter(x => x.id !== id));

  const simulate = () => {
    const a = alerts[0];
    if (a) navigate('AlertTriggered', { alert: { ticker: a.ticker, price: a.targetPrice, direction: a.direction } });
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="bg-white border-b border-gray-100 px-4 pt-10 pb-4">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-400 uppercase tracking-wide font-semibold">TradeEasy</p>
            <h1 className="text-xl font-bold text-gray-900 mt-0.5">Price Alerts</h1>
          </div>
          <button
            onClick={() => navigate('CreateAlert', { ticker: null })}
            className="w-9 h-9 rounded-full bg-teal-600 flex items-center justify-center text-white text-xl font-light shadow"
          >
            +
          </button>
        </div>
        {alerts.length > 0 && (
          <div className="mt-3 flex gap-2">
            <span className="text-xs bg-teal-50 text-teal-700 px-2 py-0.5 rounded-full font-medium">{alerts.filter(a => a.active).length} active</span>
            <button onClick={simulate} className="text-xs bg-amber-50 text-amber-700 px-2 py-0.5 rounded-full font-medium">▶ Simulate trigger</button>
          </div>
        )}
      </div>

      {/* Alert list */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {alerts.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-center">
            <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center text-2xl mb-3">🔔</div>
            <p className="font-semibold text-gray-700">No alerts yet</p>
            <p className="text-sm text-gray-400 mt-1 mb-4">Set a price threshold on any stock<br />and we'll notify you when it hits.</p>
            <button onClick={() => navigate('CreateAlert', { ticker: null })} className="px-5 py-2.5 bg-teal-600 text-white text-sm font-semibold rounded-xl">
              Set First Alert
            </button>
          </div>
        ) : (
          alerts.map(alert => (
            <div key={alert.id} className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-gray-900 text-base">{alert.ticker}</span>
                    <span className={`text-xs px-1.5 py-0.5 rounded font-semibold ${
                      alert.direction === 'above' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
                    }`}>
                      {alert.direction === 'above' ? '▲' : '▼'} ${alert.targetPrice.toFixed(2)}
                    </span>
                  </div>
                  <p className="text-xs text-gray-400 mt-0.5">{alert.name} · Current: ${alert.currentPrice.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`w-2 h-2 rounded-full ${alert.active ? 'bg-teal-400' : 'bg-gray-300'}`} />
                  <button onClick={() => deleteAlert(alert.id)} className="text-gray-300 hover:text-red-400 text-sm">✕</button>
                </div>
              </div>
              <div className="mt-2 h-1.5 rounded-full bg-gray-100 overflow-hidden">
                <div
                  className={`h-full rounded-full transition-all ${
                    alert.direction === 'above' ? 'bg-green-400' : 'bg-red-400'
                  }`}
                  style={{ width: `${Math.min(100, (alert.currentPrice / alert.targetPrice) * 100)}%` }}
                />
              </div>
              <p className="text-[10px] text-gray-400 mt-1">
                {alert.direction === 'above'
                  ? `${((alert.targetPrice - alert.currentPrice) / alert.currentPrice * 100).toFixed(1)}% away`
                  : `${((alert.currentPrice - alert.targetPrice) / alert.targetPrice * 100).toFixed(1)}% away`}
              </p>
            </div>
          ))
        )}
      </div>

      {/* Bottom nav */}
      <div className="border-t border-gray-100 px-6 py-3 flex justify-around">
        <button className="flex flex-col items-center gap-0.5">
          <span className="text-teal-600 text-lg">🔔</span>
          <span className="text-[10px] font-semibold text-teal-600">Alerts</span>
        </button>
        <button onClick={() => navigate('Watchlist')} className="flex flex-col items-center gap-0.5">
          <span className="text-gray-400 text-lg">★</span>
          <span className="text-[10px] text-gray-400">Watchlist</span>
        </button>
      </div>
    </div>
  );
}

