import { useState } from 'react';
import { watchlistItems } from '../data/mock-data';

export default function CreateAlert({ navigate, ticker }: { navigate: (s: string, p?: any) => void; ticker: string | null }) {
  const item = ticker ? watchlistItems.find(w => w.ticker === ticker) : null;
  const [selectedTicker, setSelectedTicker] = useState(ticker || watchlistItems[0].ticker);
  const [direction, setDirection] = useState<'above' | 'below'>('above');
  const current = watchlistItems.find(w => w.ticker === selectedTicker);
  const [targetPrice, setTargetPrice] = useState(
    current ? (direction === 'above' ? (current.price * 1.05).toFixed(2) : (current.price * 0.95).toFixed(2)) : ''
  );

  const handleCreate = () => {
    navigate('AlertList');
  };

  return (
    <div className="flex flex-col h-full">
      <div className="bg-white border-b border-gray-100 px-4 pt-10 pb-4 flex items-center gap-3">
        <button onClick={() => navigate('AlertList')} className="text-gray-400 text-lg">←</button>
        <h1 className="text-lg font-bold text-gray-900">New Alert</h1>
      </div>

      <div className="flex-1 px-4 py-6 space-y-6">
        {/* Stock picker */}
        <div>
          <label className="text-xs font-semibold text-gray-500 uppercase tracking-wide block mb-2">Stock</label>
          <div className="space-y-2">
            {watchlistItems.map(w => (
              <button
                key={w.ticker}
                onClick={() => setSelectedTicker(w.ticker)}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border transition-all ${
                  selectedTicker === w.ticker
                    ? 'border-teal-500 bg-teal-50'
                    : 'border-gray-100 bg-white'
                }`}
              >
                <div className="text-left">
                  <p className="font-semibold text-gray-900 text-sm">{w.ticker}</p>
                  <p className="text-xs text-gray-400">{w.name}</p>
                </div>
                <div className="text-right">
                  <p className="font-semibold text-gray-900 text-sm">${w.price.toFixed(2)}</p>
                  <p className={`text-xs font-medium ${w.change >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                    {w.change >= 0 ? '+' : ''}{w.change.toFixed(2)}%
                  </p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Direction */}
        <div>
          <label className="text-xs font-semibold text-gray-500 uppercase tracking-wide block mb-2">Alert when price goes</label>
          <div className="flex gap-3">
            <button
              onClick={() => setDirection('above')}
              className={`flex-1 py-2.5 rounded-xl text-sm font-semibold border transition-all ${
                direction === 'above' ? 'bg-green-50 border-green-400 text-green-700' : 'bg-white border-gray-200 text-gray-500'
              }`}
            >
              ▲ Above
            </button>
            <button
              onClick={() => setDirection('below')}
              className={`flex-1 py-2.5 rounded-xl text-sm font-semibold border transition-all ${
                direction === 'below' ? 'bg-red-50 border-red-400 text-red-700' : 'bg-white border-gray-200 text-gray-500'
              }`}
            >
              ▼ Below
            </button>
          </div>
        </div>

        {/* Target price */}
        <div>
          <label className="text-xs font-semibold text-gray-500 uppercase tracking-wide block mb-2">Target price</label>
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 font-semibold">$</span>
            <input
              type="number"
              value={targetPrice}
              onChange={e => setTargetPrice(e.target.value)}
              className="w-full pl-8 pr-4 py-3.5 rounded-xl border border-gray-200 text-gray-900 font-semibold text-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent"
              placeholder="0.00"
            />
          </div>
          {current && targetPrice && (
            <p className="text-xs text-gray-400 mt-1.5 pl-1">
              Current: ${current.price.toFixed(2)} · {direction === 'above' ? '+' : '-'}
              {Math.abs(((parseFloat(targetPrice) - current.price) / current.price) * 100).toFixed(1)}% from now
            </p>
          )}
        </div>
      </div>

      <div className="px-4 pb-8">
        <button
          onClick={handleCreate}
          disabled={!targetPrice || parseFloat(targetPrice) <= 0}
          className="w-full py-4 bg-teal-600 disabled:bg-gray-200 text-white disabled:text-gray-400 font-bold text-base rounded-2xl transition-colors"
        >
          Set Alert
        </button>
      </div>
    </div>
  );
}

